  },
  {
    "id": "29206:wikipedia:ecaf2cb88849",
    "cityId": "29206",
    "category": "文化財",
    "text": "桜井市の石位寺には、重要文化財の石造浮彫伝薬師三尊像があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29206:wikipedia:94a8eb8d7211",
    "cityId": "29206",
    "category": "古道",
    "text": "桜井市には山の辺の道や初瀬街道など、歴史をたどれる古道が通っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29206:wikipedia:4844056dd879",
    "cityId": "29206",
    "category": "文化財",
    "text": "桜井市の山田寺跡は、国の特別史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29206:wikipedia:affc9b791c91",
    "cityId": "29206",
    "category": "古墳",
    "text": "桜井市の文殊院西古墳は、国の特別史跡です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29206:wikipedia:604b68ddae3e",
    "cityId": "29206",
    "category": "伝統行事",
    "text": "桜井市の「江包・大西の御綱」は、国の重要無形民俗文化財に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29206:wikipedia:e122246c15f0",
    "cityId": "29206",
    "category": "交流",
    "text": "桜井市は1989年、フランスのシャルトル市と友好都市提携を結びました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%A1%9C%E4%BA%95%E5%B8%82&oldid=111061527",
  },
  {
    "id": "29207:wikipedia:1228a5ef45f6",
    "cityId": "29207",
    "category": "地名",
    "text": "市名は「五條市」ですが、JRの駅名は「五条駅」と書きます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:27aaa607a3a6",
    "cityId": "29207",
    "category": "歴史",
    "text": "五條市は1957年、五條町・野原町など8町村の合併で発足しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:2c52d0890a85",
    "cityId": "29207",
    "category": "歴史",
    "text": "五條市は2005年に西吉野村と大塔村を編入しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:dfa6b5df4efd",
    "cityId": "29207",
    "category": "自然",
    "text": "五條市の市の木はクスノキ、市の花はキキョウです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:25abbc421076",
    "cityId": "29207",
    "category": "地理",
    "text": "五條市を西へ流れる吉野川は、和歌山県では紀の川と呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:9badcd91fc50",
    "cityId": "29207",
    "category": "歴史",
    "text": "五條は大和と紀伊を結ぶ交通の要衝として発展しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:68ab79193dc9",
    "cityId": "29207",
    "category": "歴史",
    "text": "奈良時代の藤原仲麻呂が創建した栄山寺八角堂は、五條市に残る国宝です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:a242aa18d2a9",
    "cityId": "29207",
    "category": "文化財",
    "text": "五條市の栄山寺は、八角堂だけでなく梵鐘も国宝に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:e5a4b1664c9d",
    "cityId": "29207",
    "category": "歴史",
    "text": "1348年、後村上天皇は吉野から現在の五條市西吉野町の賀名生へ移りました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:6417baf36a09",
    "cityId": "29207",
    "category": "歴史",
    "text": "松倉重政は、五條の新町を城下町として整備しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:6ebe7ae160cb",
    "cityId": "29207",
    "category": "歴史",
    "text": "五條には1795年に代官所が設けられ、南大和の統治拠点となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:cfb372864c14",
    "cityId": "29207",
    "category": "歴史",
    "text": "1863年の天誅組の変は、五條代官所への襲撃から始まりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:e223315a3783",
    "cityId": "29207",
    "category": "歴史",
    "text": "五條市の櫻井寺には、天誅組の本陣が置かれました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:a6edfa6c4721",
    "cityId": "29207",
    "category": "町並み",
    "text": "五條新町は、旧紀州街道沿いに江戸時代の雰囲気を残す町並みです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:153944170cc2",
    "cityId": "29207",
    "category": "文化財",
    "text": "五條新町は、重要伝統的建造物群保存地区に選定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:32e7fa8b43fd",
    "cityId": "29207",
    "category": "建築",
    "text": "五條市の栗山家住宅は1607年築。建築年代の分かる非常に古い民家です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:d7c02d23657a",
    "cityId": "29207",
    "category": "建築",
    "text": "市立五條文化博物館は安藤忠雄の設計で、円筒形の外観が特徴です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:cf5acaa82ad5",
    "cityId": "29207",
    "category": "展示",
    "text": "五條市民俗資料館では、旧五條代官所の長屋門が使われています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:602ef414313a",
    "cityId": "29207",
    "category": "交通史",
    "text": "五條市には、完成しなかった鉄道「五新線」の構造物が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:86d38c456ecb",
    "cityId": "29207",
    "category": "自然",
    "text": "五條市の「二見の大ムク」は、国の天然記念物です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:aa37d5df2a3d",
    "cityId": "29207",
    "category": "特産品",
    "text": "五條市は柿の一大産地で、市内には柿博物館もあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:aebdd02ef5d5",
    "cityId": "29207",
    "category": "自然",
    "text": "五條市西吉野町の賀名生梅林は、梅の名所として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:d18af4efd21b",
    "cityId": "29207",
    "category": "天文",
    "text": "五條市大塔町の「星のくに」には、天文台やプラネタリウムがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:1032527e81a4",
    "cityId": "29207",
    "category": "寺社",
    "text": "五條市の生蓮寺は、「雨晴れ地蔵」の寺として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:5c8e25c9ded0",
    "cityId": "29207",
    "category": "寺社",
    "text": "五條市の如意寺は、辯天宗の総本山です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:7f5b915a712a",
    "cityId": "29207",
    "category": "寺社",
    "text": "五條市には、阿田隼人にゆかりのある阿陀比売神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:8b42ef1b2cbf",
    "cityId": "29207",
    "category": "伝統行事",
    "text": "五條市の念仏寺陀々堂には、「鬼はしり」という伝統行事があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:0d54ef34559f",
    "cityId": "29207",
    "category": "伝統行事",
    "text": "五條市大塔町には、惣谷狂言や篠原踊が伝わっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:9704bd93bac5",
    "cityId": "29207",
    "category": "行事",
    "text": "五條市の吉野川祭りは、大川橋の河川敷を会場とする祭りです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29207:wikipedia:72d5a1bb95af",
    "cityId": "29207",
    "category": "歴史",
    "text": "明治初期には、五條を拠点とする「五條県」が置かれた時期があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%BA%94%E6%A2%9D%E5%B8%82&oldid=111054495",
  },
  {
    "id": "29208:wikipedia:9a6a3ff63eb3",
    "cityId": "29208",
    "category": "地名",
    "text": "御所市は「ごせし」と読みます。市名の由来には複数の説があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:0133410fe755",
    "cityId": "29208",
    "category": "地名",
    "text": "御所の名は、葛城川にあった「五つの瀬」に由来するという説があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:2dd22cbed460",
    "cityId": "29208",
    "category": "地名",
    "text": "御所の名を、古代豪族の巨勢氏の「こせ」が転じたものとする説もあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:1491c231f7e5",
    "cityId": "29208",
    "category": "歴史",
    "text": "「御所郷」という地名は、16世紀の文書に見られます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:4dc20e94215f",
    "cityId": "29208",
    "category": "自然",
    "text": "御所市の市の木はクスノキ、市の花はツツジです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:cd41fb157f4e",
    "cityId": "29208",
    "category": "地理",
    "text": "御所市から南へ風の森峠を越えると、五條市に入ります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:837d6d6ff5da",
    "cityId": "29208",
    "category": "地名",
    "text": "御所市の中心部には、大字名がなく番地だけで表す住所があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:4fd5a825d8f0",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所市一帯は、古代豪族・葛城氏の本拠地でした。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:389630da4314",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所市の古瀬は巨勢氏の拠点で、巨勢寺塔跡が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:ad153c2c940d",
    "cityId": "29208",
    "category": "遺跡",
    "text": "御所市では2004年に極楽寺ヒビキ遺跡が発見されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:7b33b0d20d17",
    "cityId": "29208",
    "category": "遺跡",
    "text": "御所市の秋津遺跡は、2009年に発見された遺跡です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:d2c99465ec53",
    "cityId": "29208",
    "category": "歴史",
    "text": "中世の御所には、葛城川を挟んで西御所・東御所の環濠集落がありました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:99e0a8b123ba",
    "cityId": "29208",
    "category": "町並み",
    "text": "御所の東側の集落は、圓照寺を中心とした寺内町の性格を持っていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:e4dda1d5b15e",
    "cityId": "29208",
    "category": "歴史",
    "text": "桑山元晴は1600年に西御所へ陣屋を置き、「御所まち」の整備を進めました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:4de061366c3a",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所藩は1629年に廃藩となり、その後の御所は幕府領になりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:6bc9a28b83e2",
    "cityId": "29208",
    "category": "産業",
    "text": "江戸時代の御所は、木綿織業や油をしぼる産業でも栄えました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:4180b2f0bd3c",
    "cityId": "29208",
    "category": "歴史",
    "text": "1863年、現在の御所市櫛羅に永井家の陣屋が設けられました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:9dbe546c59bb",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所市の九品寺には、櫛羅陣屋の玄関を移築した遺構があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:32b12ba67dea",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所市は1958年、御所町・葛村・葛上村・大正村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:fe1b4a1af1ec",
    "cityId": "29208",
    "category": "歴史",
    "text": "御所市は、全国水平社の創立に関わった人々を生んだ地です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:82d3c7d6e4ca",
    "cityId": "29208",
    "category": "古道",
    "text": "御所市の葛城古道は、葛城山麓の歴史をたどる道です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:d94414d599e1",
    "cityId": "29208",
    "category": "寺社",
    "text": "御所市には、葛城一言主神社や高天彦神社などの古社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:2ab0db086c50",
    "cityId": "29208",
    "category": "寺社",
    "text": "御所市の鴨都波神社と高鴨神社は、ともに延喜式に名を記す古社です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:d243d682aae1",
    "cityId": "29208",
    "category": "寺社",
    "text": "御所市には、葛木御歳神社や葛木水分神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:8b50d7b6ae41",
    "cityId": "29208",
    "category": "古墳",
    "text": "御所市には、古代の墓が集まる巨勢山古墳群があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:864aaef63709",
    "cityId": "29208",
    "category": "建築",
    "text": "御所市の歴史的な建物には、中井家住宅があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:58b0260ca33d",
    "cityId": "29208",
    "category": "文化",
    "text": "御所市のマスコット「ゴセンちゃん」は、神の使いという設定です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29208:wikipedia:21521c1eb1e1",
    "cityId": "29208",
    "category": "文化",
    "text": "ゴセンちゃんの緑の髪は葛城山と金剛山を表し、髪飾りにはツツジが使われています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%89%80%E5%B8%82&oldid=111061478",
  },
  {
    "id": "29209:wikipedia:dff65836532b",
    "cityId": "29209",
    "category": "歴史",
    "text": "生駒市は1971年11月1日に市制を施行しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:fe17466b0d11",
    "cityId": "29209",
    "category": "自然",
    "text": "生駒市の市の木はイチイガシ、市の花はキクです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:28835eb1ab18",
    "cityId": "29209",
    "category": "町並み",
    "text": "生駒の町は、生駒聖天と呼ばれる宝山寺の門前町として発展しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:954fc3977914",
    "cityId": "29209",
    "category": "地理",
    "text": "生駒市は、生駒山地と矢田丘陵などに囲まれた起伏の多い市です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:9a1ad373af9f",
    "cityId": "29209",
    "category": "地理",
    "text": "生駒市では、北部を富雄川、中南部を竜田川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:ca9ca8b15fda",
    "cityId": "29209",
    "category": "交通",
    "text": "生駒ケーブルは、参拝や観光だけでなく日常の通勤にも使われています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:35cc8b3b2dc0",
    "cityId": "29209",
    "category": "古道",
    "text": "生駒には、大阪と奈良を結んだ暗越奈良街道や清滝街道が通っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:c2c833d192fa",
    "cityId": "29209",
    "category": "伝統工芸",
    "text": "高山の茶筌づくりは、かつて一子相伝で受け継がれたと伝えられています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:9e893634165f",
    "cityId": "29209",
    "category": "歴史",
    "text": "1736年刊行の『大和志』には、茶筌が高山村の特産物として記されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:0f6797b94565",
    "cityId": "29209",
    "category": "交通史",
    "text": "1914年の鉄道開通で、生駒トンネルを通じて大阪と奈良が結ばれました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:e418deb24e82",
    "cityId": "29209",
    "category": "交通史",
    "text": "1918年に開業した生駒ケーブルは、日本最初のケーブルカーです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:80a0f97247b8",
    "cityId": "29209",
    "category": "歴史",
    "text": "生駒山上遊園地は、1929年に開業しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:1c7213085d5e",
    "cityId": "29209",
    "category": "交通史",
    "text": "大阪と奈良を結ぶ阪奈道路は、1959年に開通しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:57c640572d06",
    "cityId": "29209",
    "category": "交通史",
    "text": "信貴生駒スカイラインは、1964年に開通しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:04e572c752a1",
    "cityId": "29209",
    "category": "交通史",
    "text": "1986年、生駒から地下鉄中央線への直通運転が始まりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:6837c0f052fc",
    "cityId": "29209",
    "category": "交通史",
    "text": "2006年に近鉄けいはんな線が延伸し、白庭台駅と学研北生駒駅が開業しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:32508a5e9308",
    "cityId": "29209",
    "category": "文化財",
    "text": "生駒市の長弓寺は、本堂が国宝に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:ab6e443511d0",
    "cityId": "29209",
    "category": "寺社",
    "text": "生駒市の往馬坐伊古麻都比古神社は、往馬大社や生駒神社とも呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:383c2102d141",
    "cityId": "29209",
    "category": "史跡",
    "text": "生駒市高山地区には、高山城跡があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:77fc1503dbc8",
    "cityId": "29209",
    "category": "名所",
    "text": "生駒市には、高山八幡宮や高山竹林園があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:1ad39e653c68",
    "cityId": "29209",
    "category": "自然",
    "text": "生駒市の自然に親しめる場所に、くろんど池自然公園があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:fd4027148cf9",
    "cityId": "29209",
    "category": "展示",
    "text": "生駒ふるさとミュージアムは、2014年に開館しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29209:wikipedia:002aa5677561",
    "cityId": "29209",
    "category": "文化",
    "text": "2015年、生駒市図書館でビブリオバトルの全国大会が開催されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%94%9F%E9%A7%92%E5%B8%82&oldid=111307238",
  },
  {
    "id": "29210:wikipedia:7e4d305633eb",
    "cityId": "29210",
    "category": "地理",
    "text": "香芝市は、二上山の東麓に広がる扇状地に位置します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:e828f6b8631e",
    "cityId": "29210",
    "category": "自然",
    "text": "香芝市の市の木はカシ、市の花はスミレです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:382f02460d40",
    "cityId": "29210",
    "category": "地名",
    "text": "「香芝」の名は、下田の鹿島神社に由来するといわれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:f94a997c9f52",
    "cityId": "29210",
    "category": "歴史",
    "text": "香芝町は1956年、五位堂・下田・二上・志都美の4村が合併して発足しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:e5b6cf51c127",
    "cityId": "29210",
    "category": "歴史",
    "text": "香芝市は1991年10月1日に、奈良県で10番目の市となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:02f787967a15",
    "cityId": "29210",
    "category": "文化",
    "text": "香芝市のマスコット「カッシー」は、2001年に誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:29dbfa75b161",
    "cityId": "29210",
    "category": "展示",
    "text": "香芝市のふたかみ文化センターには、二上山博物館と市民図書館があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:e5da57a50286",
    "cityId": "29210",
    "category": "歴史",
    "text": "香芝市のふたかみ文化センターは、1992年に開館しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:98dd8075bd94",
    "cityId": "29210",
    "category": "交通史",
    "text": "JR香芝駅は、2004年に下田駅から改称されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:89491d4055e9",
    "cityId": "29210",
    "category": "交通史",
    "text": "香芝市のJR五位堂駅は、2004年に開業しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:429d2225ffdb",
    "cityId": "29210",
    "category": "交通",
    "text": "香芝市の五位堂駅とJR五位堂駅は、別の鉄道会社の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:ba1a54fa8cc0",
    "cityId": "29210",
    "category": "交通",
    "text": "香芝市の近鉄下田駅は大阪線、二上山駅は南大阪線の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:b19a32270bf7",
    "cityId": "29210",
    "category": "特産品",
    "text": "香芝市の特産品には、靴下や鋳物があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:ee2285851418",
    "cityId": "29210",
    "category": "特産品",
    "text": "香芝市の特産として挙げられる「金剛砂」は、ざくろ石のことです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:d605c17a778d",
    "cityId": "29210",
    "category": "自然",
    "text": "香芝市穴虫の屯鶴峯は、「どんづるぼう」と読む奇勝です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:6dd49ab6be19",
    "cityId": "29210",
    "category": "文化財",
    "text": "香芝市の屯鶴峯は、奈良県の天然記念物に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:dd995db85e67",
    "cityId": "29210",
    "category": "古墳",
    "text": "香芝市の平野塚穴山古墳は、国の史跡です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:6bd6a718f870",
    "cityId": "29210",
    "category": "古墳",
    "text": "香芝市の狐井城山古墳は、市内最大の前方後円墳です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:924b47f21637",
    "cityId": "29210",
    "category": "寺社",
    "text": "香芝市良福寺の阿日寺は、「ぽっくり寺」とも呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:724d41b3ce3f",
    "cityId": "29210",
    "category": "寺社",
    "text": "香芝市には、穴虫と逢坂の両方に大坂山口神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:31fda3d41b7d",
    "cityId": "29210",
    "category": "自然",
    "text": "香芝市の千股池は、奈良県景観資産に登録されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:2dc42db7c553",
    "cityId": "29210",
    "category": "自然",
    "text": "香芝市の専称寺には、「尋源桜」と呼ばれるしだれ桜があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:a0c119e9f6c1",
    "cityId": "29210",
    "category": "文化財",
    "text": "香芝市の尼寺廃寺跡は、国の史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:cf00461730d8",
    "cityId": "29210",
    "category": "地名",
    "text": "香芝市の「尼寺」という地名は、「にんじ」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:31ab579c740d",
    "cityId": "29210",
    "category": "地名",
    "text": "香芝市の「逢坂」は、「おうさか」と読む地名です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:411dd904ef51",
    "cityId": "29210",
    "category": "行事",
    "text": "香芝市の冬の祭り「冬彩」は、2001年に始まりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:878b061099a9",
    "cityId": "29210",
    "category": "文化",
    "text": "香芝市には、市民有志によるご当地検定「香芝検定」があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:e8da75887cb5",
    "cityId": "29210",
    "category": "寺社",
    "text": "香芝市の志都美神社は、今泉地区にあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:ad35bc89dfec",
    "cityId": "29210",
    "category": "古墳",
    "text": "香芝市北今市には、顕宗天皇陵に治定された古墳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29210:wikipedia:4714f92e360b",
    "cityId": "29210",
    "category": "古墳",
    "text": "香芝市今泉には、武烈天皇陵に治定された古墳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%A6%99%E8%8A%9D%E5%B8%82&oldid=111150966",
  },
  {
    "id": "29211:wikipedia:e176ad5526a3",
    "cityId": "29211",
    "category": "歴史",
    "text": "葛城市は2004年10月1日、新庄町と當麻町の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:1d2737580d35",
    "cityId": "29211",
    "category": "地名",
    "text": "葛城市の市名は、旧2町が属していた北葛城郡に由来します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:ebc0b3a7e5de",
    "cityId": "29211",
    "category": "地名",
    "text": "葛城市の公式な「葛」の字は、下の部分が「ヒ」の字体です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:f61940f3b9f5",
    "cityId": "29211",
    "category": "地理",
    "text": "葛城市という名ですが、大和葛城山の山頂は隣の御所市にあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:4fbe689fda7a",
    "cityId": "29211",
    "category": "自然",
    "text": "葛城市の市の木はイチイガシとクスノキ、市の花はボタンとキクです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:e075dc1e9337",
    "cityId": "29211",
    "category": "自然",
    "text": "葛城市の市の鳥はウグイスです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:8f8670277cae",
    "cityId": "29211",
    "category": "地理",
    "text": "葛城市には二上山や岩橋山があり、市内には高田川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:820b366e323c",
    "cityId": "29211",
    "category": "歴史",
    "text": "中世の葛城市域では、布施氏が布施城や新庄城を拠点としていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:5ee433a17767",
    "cityId": "29211",
    "category": "歴史",
    "text": "関ヶ原の戦いの後、桑山一晴が新庄の屋敷山に陣屋を整備しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:b0c9e202aa0b",
    "cityId": "29211",
    "category": "歴史",
    "text": "新庄は陣屋町から、高野街道の宿場町へと役割を変えていきました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:723cf62a2133",
    "cityId": "29211",
    "category": "産業",
    "text": "葛城市では、農家の家内工業としてメリヤスや靴下づくりが行われていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:ad565be85471",
    "cityId": "29211",
    "category": "農業",
    "text": "葛城市は、二輪菊の産地として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:64dd5f3900ee",
    "cityId": "29211",
    "category": "文化",
    "text": "葛城市には、相撲をテーマとする「相撲館 けはや座」があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:60d8fe3ea7aa",
    "cityId": "29211",
    "category": "寺社",
    "text": "葛城市の當麻寺は、新西国三十三箇所観音霊場の第11番札所です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:b54ee5a3f83b",
    "cityId": "29211",
    "category": "伝統行事",
    "text": "葛城市の當麻寺では、「お練供養」と呼ばれる行事が行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:e1da0e0b31c1",
    "cityId": "29211",
    "category": "文化財",
    "text": "葛城市の屋敷山古墳は、国の史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:b7d53f563be1",
    "cityId": "29211",
    "category": "文化財",
    "text": "葛城市の二塚古墳も、国の史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:bffc4837d7ae",
    "cityId": "29211",
    "category": "寺社",
    "text": "葛城市の葛木坐火雷神社は、「笛吹神社」とも呼ばれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:d7c1b0090d7f",
    "cityId": "29211",
    "category": "寺社",
    "text": "葛城市の長尾神社は、延喜式に名を記す古社です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:96079cf317d0",
    "cityId": "29211",
    "category": "寺社",
    "text": "葛城市には、石光寺や博西神社などの寺社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:9e72f93aee11",
    "cityId": "29211",
    "category": "展示",
    "text": "葛城市の歴史を学べる施設に、葛城市歴史博物館があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:7534108347c1",
    "cityId": "29211",
    "category": "古墳",
    "text": "葛城市には、飯豊天皇陵に治定された古墳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:c5d9b71c6ead",
    "cityId": "29211",
    "category": "城跡",
    "text": "葛城市の史跡には、二上山城の跡があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:4c6b02f37d4c",
    "cityId": "29211",
    "category": "名所",
    "text": "葛城市の屋敷山古墳周辺は、屋敷山公園になっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:038d4c26a8a8",
    "cityId": "29211",
    "category": "名所",
    "text": "葛城市には、山麓の自然に親しめる葛城山麓公園があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29211:wikipedia:acfb04a04444",
    "cityId": "29211",
    "category": "行事",
    "text": "葛城市では、かつらぎ花火大会が開かれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E8%91%9B%E5%9F%8E%E5%B8%82&oldid=111237285",
  },
  {
    "id": "29212:wikipedia:fff2e5f9f23c",
    "cityId": "29212",
    "category": "歴史",
    "text": "宇陀市は2006年、菟田野町・大宇陀町・榛原町・室生村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:7559e637fa0b",
    "cityId": "29212",
    "category": "自然",
    "text": "宇陀市の市の木はヒノキ、市の花はスズラン、市の鳥はウグイスです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:81ff6d92d834",
    "cityId": "29212",
    "category": "地理",
    "text": "宇陀市は大和高原の南端に位置し、四方を山に囲まれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:54ce222d633c",
    "cityId": "29212",
    "category": "地理",
    "text": "宇陀市では、宇陀川や芳野川沿いの平地に町が広がっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:1f4e2f796c9c",
    "cityId": "29212",
    "category": "文学",
    "text": "宇陀市の阿騎野は、柿本人麻呂が「かぎろひ」を詠んだ地として知られます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:147bc2ebba2a",
    "cityId": "29212",
    "category": "歴史",
    "text": "宇陀市の榛原は、伊勢街道の分岐点にある宿場町として栄えました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:f94a2d7ec455",
    "cityId": "29212",
    "category": "歴史",
    "text": "宇陀市榛原の旧旅籠「あぶらや」には、本居宣長が宿泊しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:5cbd4832bdc0",
    "cityId": "29212",
    "category": "町並み",
    "text": "宇陀市松山地区は、2006年に重要伝統的建造物群保存地区に選定されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:5b5dbe1fb1b7",
    "cityId": "29212",
    "category": "史跡",
    "text": "宇陀市の松山西口関門は、通称「黒門」。松山城下町の旧大手門です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:b5652c85ba5a",
    "cityId": "29212",
    "category": "史跡",
    "text": "宇陀市の森野旧薬園は、国の史跡に指定された民間の薬草園です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:abb18b474731",
    "cityId": "29212",
    "category": "展示",
    "text": "宇陀市の「薬の館」は、江戸時代末期に建てられた旧細川家住宅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:7d388a411b85",
    "cityId": "29212",
    "category": "建築",
    "text": "宇陀市松山地区の「千軒舎」は、旧内藤家の建物です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:2c594ffc0f98",
    "cityId": "29212",
    "category": "城跡",
    "text": "宇陀市の宇陀松山城跡は、国の史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:39c4e6f9bd5a",
    "cityId": "29212",
    "category": "文化財",
    "text": "宇陀市の室生寺には、国宝の五重塔があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:1fba7e130475",
    "cityId": "29212",
    "category": "文化財",
    "text": "宇陀市の宇太水分神社は、国宝の社殿を持つ神社です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:17e63e427dd0",
    "cityId": "29212",
    "category": "寺社",
    "text": "宇陀市の阿紀神社には、能舞台があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:606051df1b64",
    "cityId": "29212",
    "category": "文化財",
    "text": "宇陀市の光明寺は、山門が県の重要文化財に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:bdfc02b484fc",
    "cityId": "29212",
    "category": "文化財",
    "text": "宇陀市の万法寺は、本堂が県の重要文化財です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:6bb97ca9ac96",
    "cityId": "29212",
    "category": "芸術",
    "text": "宇陀市の慶恩寺には、水井康雄の彫刻「笑石II」が置かれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:a86ee793a346",
    "cityId": "29212",
    "category": "自然",
    "text": "宇陀市の又兵衛桜は、「瀧桜」とも呼ばれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:4f9dd07cf59a",
    "cityId": "29212",
    "category": "自然",
    "text": "宇陀市菟田野の水分桜は、芳野川の堤防に連なる桜並木です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:82cceb2fd8b0",
    "cityId": "29212",
    "category": "自然",
    "text": "宇陀市には、国の天然記念物であるカザグルマの自生地があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:919aaa005c06",
    "cityId": "29212",
    "category": "名所",
    "text": "宇陀市の阿騎野・人麻呂公園には、復元建物や柿本人麻呂像があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:5078b3710bce",
    "cityId": "29212",
    "category": "名所",
    "text": "宇陀市には、「かぎろひの丘」とも呼ばれる万葉公園があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:c49e45874cf1",
    "cityId": "29212",
    "category": "食文化",
    "text": "宇陀市の大宇陀・榛原では、食肉用の宇陀牛が知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:e0fca0d2d616",
    "cityId": "29212",
    "category": "寺社",
    "text": "宇陀市には、大野寺や仏隆寺などの古寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:6c2b0f9b4e13",
    "cityId": "29212",
    "category": "寺社",
    "text": "宇陀市には、八咫烏神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:4db9c1aa2047",
    "cityId": "29212",
    "category": "展示",
    "text": "宇陀市には、民芸品に触れられる大亀和尚民芸館があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:ef3d2d726685",
    "cityId": "29212",
    "category": "地名",
    "text": "宇陀市の地域名「菟田野」は、「うたの」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29212:wikipedia:6c5b5658d2ca",
    "cityId": "29212",
    "category": "歴史",
    "text": "宇陀市は発足時に地域自治区を設け、2011年に地名から「区」を外しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%AE%87%E9%99%80%E5%B8%82&oldid=110004210",
  },
  {
    "id": "29322:wikipedia:782166e0a632",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村の村の花はヤマツツジです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:2566042b590d",
    "cityId": "29322",
    "category": "地理",
    "text": "山添村は奈良県の北東部にあり、三重県と接しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:318e81e0ff5f",
    "cityId": "29322",
    "category": "地理",
    "text": "山添村は大和高原に位置し、村域の約8割を森林が占めます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:65794fe26804",
    "cityId": "29322",
    "category": "地理",
    "text": "山添村の地形は西側が高く、東へ向かって低くなっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:209c8234cde6",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村内を流れる川は、木津川の水系に属しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:c5a83c3f519f",
    "cityId": "29322",
    "category": "地理",
    "text": "山添村の北東側には名張川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:a4a8e2834503",
    "cityId": "29322",
    "category": "地名",
    "text": "山添村の名は、合併前の村が属した山辺郡と添上郡から一字ずつ取ったものです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:b58b2c022d6c",
    "cityId": "29322",
    "category": "地名",
    "text": "山添という村名には「山に添う村」という願いも込められています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:9bd835619a7b",
    "cityId": "29322",
    "category": "歴史",
    "text": "山添村は1956年、東山村・波多野村・豊原村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:53c2e9f258f9",
    "cityId": "29322",
    "category": "歴史",
    "text": "1957年、山添村の水間・別所地区は田原村へ編入されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:ac2b5f105835",
    "cityId": "29322",
    "category": "農業",
    "text": "山添村の主な農産物には、大和茶と米があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:7588effacd92",
    "cityId": "29322",
    "category": "農業",
    "text": "山添村では、茶園の霜害対策として防霜設備の導入が進められてきました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:8222268344c0",
    "cityId": "29322",
    "category": "交通",
    "text": "山添村を東西に通る幹線道路が名阪国道です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:33499a8cdaa6",
    "cityId": "29322",
    "category": "交通",
    "text": "山添村には鉄道の駅がありません。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:bba10a733a5b",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村の神野山は、奈良県の名勝に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:a33ddc78bcf7",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村の鍋倉渓は、巨岩が帯状に並ぶ奈良県指定天然記念物です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:c97ee1b165f3",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村の鍋倉渓では、岩の下を流れる水の音を聞くことができます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:37e1c21a8eae",
    "cityId": "29322",
    "category": "自然",
    "text": "山添村の布目湖は、布目ダムによってできた湖です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:b5b61ad07d64",
    "cityId": "29322",
    "category": "神社",
    "text": "山添村には、神波多神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:433d42ac2217",
    "cityId": "29322",
    "category": "施設",
    "text": "山添村には、モータースポーツ施設の名阪スポーツランドがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:4a71084e9e41",
    "cityId": "29322",
    "category": "文化財",
    "text": "山添村歴史民俗資料館には、旧春日小学校の講堂が使われています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:61a76e0e19bf",
    "cityId": "29322",
    "category": "文化財",
    "text": "山添村の旧春日小学校講堂は、奈良県の有形文化財に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B1%B1%E6%B7%BB%E6%9D%91&oldid=110274951",
  },
  {
    "id": "29322:wikipedia:ab915384d402",
    "cityId": "29322",
    "category": "歴史",
    "text": "山添村の毛原廃寺跡は、奈良時代の寺院の跡です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:ed47dafe8c0f",
    "cityId": "29322",
    "category": "文化財",
    "text": "山添村の毛原廃寺跡は、1926年に国の史跡に指定されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:559356f70f36",
    "cityId": "29322",
    "category": "遺跡",
    "text": "山添村の毛原廃寺跡には、金堂や塔、門の礎石が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:0f6d6c522ce5",
    "cityId": "29322",
    "category": "遺跡",
    "text": "毛原廃寺跡の北東約3kmでは、寺で使われた瓦を焼いた窯跡が見つかっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:147b02c300c4",
    "cityId": "29322",
    "category": "考古学",
    "text": "毛原廃寺跡と窯跡から出土した瓦には、同じ型で作られたものがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:732698c60eae",
    "cityId": "29322",
    "category": "考古学",
    "text": "毛原廃寺の瓦窯では、平瓦を重ねて煙道を造っていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:1ff59fead453",
    "cityId": "29322",
    "category": "考古学",
    "text": "毛原廃寺跡からは、蓮華文の軒丸瓦や唐草文の軒平瓦が出土しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29322:wikipedia:7e398b060945",
    "cityId": "29322",
    "category": "歴史",
    "text": "毛原廃寺は史料が乏しく、寺の由来には東大寺との関係を考える説もあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%AF%9B%E5%8E%9F%E5%BB%83%E5%AF%BA%E8%B7%A1&oldid=110006380",
  },
  {
    "id": "29342:wikipedia:6dc027dbb147",
    "cityId": "29342",
    "category": "自然",
    "text": "平群町の町の木はカシ、町の花はキクです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:cc866d9b236e",
    "cityId": "29342",
    "category": "地理",
    "text": "平群町は、西の生駒・信貴山地と東の矢田丘陵に挟まれています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:1eea068265eb",
    "cityId": "29342",
    "category": "自然",
    "text": "平群町を南へ流れる竜田川は、大和川に合流します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:99feb22bebbf",
    "cityId": "29342",
    "category": "歴史",
    "text": "平群町周辺は、古代の豪族・平群氏の本拠地とされています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:d704db13b804",
    "cityId": "29342",
    "category": "神社",
    "text": "平群町には、平群神社・平群坐紀氏神社・平群石床神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:faeeb301edc6",
    "cityId": "29342",
    "category": "文化財",
    "text": "平群町の朝護孫子寺は、国宝「信貴山縁起絵巻」を伝えています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:e107cf0b47ca",
    "cityId": "29342",
    "category": "歴史",
    "text": "信貴山城は、戦国時代に松永久秀の拠点となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:7e9901a507eb",
    "cityId": "29342",
    "category": "歴史",
    "text": "信貴山城は、松永久秀が滅んだ後に廃城となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:400a7416d38e",
    "cityId": "29342",
    "category": "歴史",
    "text": "平群町の前身は、1889年に20の村が合併してできた明治村です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:7bd7d6fa1e55",
    "cityId": "29342",
    "category": "歴史",
    "text": "明治村が平群村へ改称したのは1896年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:77d7c59a42c7",
    "cityId": "29342",
    "category": "歴史",
    "text": "平群村が町になったのは1971年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:bb7c31d13672",
    "cityId": "29342",
    "category": "交通",
    "text": "平群町を走る鉄道は、近鉄生駒線です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:9c978f8f92af",
    "cityId": "29342",
    "category": "交通",
    "text": "平群町内には、元山上口・平群・竜田川の3駅があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:fae1116e485a",
    "cityId": "29342",
    "category": "寺院",
    "text": "平群町の千光寺は「元山上」とも呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:6b6d30e43165",
    "cityId": "29342",
    "category": "伝承",
    "text": "平群町の千光寺には、役行者が大峯山に入る前に修行したという伝承があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:93d6d939e0b8",
    "cityId": "29342",
    "category": "寺院",
    "text": "平群町の金勝寺には、十三仏の信仰があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:13509851ecaf",
    "cityId": "29342",
    "category": "史跡",
    "text": "平群町には、長屋王と吉備内親王の墓とされる場所があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:8eb1e7754674",
    "cityId": "29342",
    "category": "文化財",
    "text": "平群町の西宮古墳は、平群中央公園の中にあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:b1c8091ae9e0",
    "cityId": "29342",
    "category": "史跡",
    "text": "平群町には、中世の山城である椿井城の跡があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:6f1538ac1c66",
    "cityId": "29342",
    "category": "文化財",
    "text": "平群町の烏土塚古墳は、国の史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:a5e232512b78",
    "cityId": "29342",
    "category": "信仰",
    "text": "平群町の信貴山は、朝護孫子寺を中心とした信仰の地です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:d2bc9a501bea",
    "cityId": "29342",
    "category": "歴史",
    "text": "平群町の信貴山城は、木沢長政が築いた城として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%B9%B3%E7%BE%A4%E7%94%BA&oldid=110769296",
  },
  {
    "id": "29342:wikipedia:7d74ab704328",
    "cityId": "29342",
    "category": "古墳",
    "text": "平群町の烏土塚古墳は、6世紀中ごろに築かれた前方後円墳です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:b06b7ba40581",
    "cityId": "29342",
    "category": "古墳",
    "text": "烏土塚古墳は全長約60.5mで、平群谷では最大の古墳です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:55aa2f7f9fe8",
    "cityId": "29342",
    "category": "考古学",
    "text": "平群町の烏土塚古墳では、1969年に発掘調査が行われました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:30db1e867a99",
    "cityId": "29342",
    "category": "古墳",
    "text": "烏土塚古墳の横穴式石室は、全長約14.2mあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:7416fcb8a92b",
    "cityId": "29342",
    "category": "古墳",
    "text": "烏土塚古墳の石室には、2基の家形石棺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:09a99ec3004b",
    "cityId": "29342",
    "category": "考古学",
    "text": "烏土塚古墳の石棺には、二上山の白色凝灰岩が使われています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:a31e569689ed",
    "cityId": "29342",
    "category": "考古学",
    "text": "烏土塚古墳では、人物や家をかたどった埴輪が見つかっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29342:wikipedia:c364f548a490",
    "cityId": "29342",
    "category": "考古学",
    "text": "烏土塚古墳からは馬具も出土していますが、葬られた人物は分かっていません。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%83%8F%E5%9C%9F%E5%A1%9A%E5%8F%A4%E5%A2%B3&oldid=110417232",
  },
  {
    "id": "29343:wikipedia:ddcdf297442b",
    "cityId": "29343",
    "category": "自然",
    "text": "三郷町の町の木はモミジ、町の花はヒマワリです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:d40e38c17081",
    "cityId": "29343",
    "category": "地理",
    "text": "三郷町は、信貴山の南東側の山麓に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:802137c7be9c",
    "cityId": "29343",
    "category": "自然",
    "text": "三郷町の南部には大和川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:fafb9f182b9f",
    "cityId": "29343",
    "category": "神社",
    "text": "三郷町の龍田大社は、風の神をまつる神社として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:6282e98bcf94",
    "cityId": "29343",
    "category": "歴史",
    "text": "三郷町の龍田大社は、古代から朝廷の崇敬を集めた二十二社の一つです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:81ee4fbdb055",
    "cityId": "29343",
    "category": "産業",
    "text": "三郷町では、江戸時代から草履や雪駄づくりが行われてきました。",
