        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%89%E9%83%B7%E7%94%BA&oldid=110636990",
  },
  {
    "id": "29343:wikipedia:021a8ac4e2b4",
    "cityId": "29343",
    "category": "特産品",
    "text": "三郷町の履物づくりから生まれた商品に「ミサトッコ」があります。",
