        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E6%9D%91&oldid=110004153",
  },
  {
    "id": "29385:wikipedia:d06454af5516",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原は、室生赤目青山国定公園の中にあります。",
