  },
  {
    "id": "29385:wikipedia:b36194bdcc41",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原は、国定公園の第一種特別地域に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:ea0f6d5412cb",
    "cityId": "29385",
    "category": "地理",
    "text": "曽爾高原は、倶留尊山と亀山の西側の斜面から麓に広がっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:302193fe837b",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原の背後にそびえる倶留尊山は、標高1,038mです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:a27b967f2b3e",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原に隣接する亀山は、標高849mです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:a66884fe84df",
    "cityId": "29385",
    "category": "地理",
    "text": "曽爾高原の平坦な部分は、標高約700mにあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:d51b25a8dbc2",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原の広さは、約38haです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:0bc52a5668bf",
    "cityId": "29385",
    "category": "風景",
    "text": "曽爾高原は、秋に一面に広がるススキで知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:682217405bbd",
    "cityId": "29385",
    "category": "自然",
    "text": "曽爾高原の「お亀池」は、湿地帯です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:cdc6b763761e",
    "cityId": "29385",
    "category": "景観保全",
    "text": "曽爾高原では、春に山焼きが行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29385:wikipedia:9fc9ef7e12c6",
    "cityId": "29385",
    "category": "施設",
    "text": "曽爾高原の周辺には、国立曽爾青少年自然の家があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%9B%BD%E7%88%BE%E9%AB%98%E5%8E%9F&oldid=111120256",
  },
  {
    "id": "29386:wikipedia:18d26deef7cb",
    "cityId": "29386",
    "category": "自然",
    "text": "御杖村の村の木はスギ、村の花はヤマザクラ、村の鳥はウグイスです。",
