  {
    "id": "29386:wikipedia:65f4f4e37b38",
    "cityId": "29386",
    "category": "地理",
    "text": "御杖村は奈良県の東端に位置し、三重県に接しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E6%9D%91&oldid=107994204",
  },
  {
    "id": "29386:wikipedia:9fbc9c7927c3",
    "cityId": "29386",
    "category": "地理",
    "text": "御杖村は、曽爾村の南側にあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E6%9D%91&oldid=107994204",
  },
  {
    "id": "29386:wikipedia:a5687c6b9c61",
    "cityId": "29386",
    "category": "自然",
    "text": "御杖村は、名張川の源流域に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E6%9D%91&oldid=107994204",
  },
  {
    "id": "29386:wikipedia:01e3fc8dd6e4",
    "cityId": "29386",
    "category": "歴史",
    "text": "御杖村には、伊勢本街道が通っています。",
