    "id": "29386:wikipedia:78d4e648a025",
    "cityId": "29386",
    "category": "寺院",
    "text": "御杖村には、東禅寺や林泉寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E6%9D%91&oldid=107994204",
  },
