  },
  {
    "id": "29386:wikipedia:02e1220e00b6",
    "cityId": "29386",
    "category": "建築",
    "text": "御杖神社の本殿は、神明造です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29386:wikipedia:a6022706f9a8",
    "cityId": "29386",
    "category": "神社",
    "text": "御杖神社では、久那斗神・八街比古神・八街比女神をまつっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29386:wikipedia:c5a69811a357",
    "cityId": "29386",
    "category": "伝承",
    "text": "御杖神社には、天照大御神をまつる地を探した倭姫命が休んだという伝承があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29386:wikipedia:90d1ef161ce4",
    "cityId": "29386",
    "category": "歴史",
    "text": "御杖神社は、延喜式神名帳に記された宇陀郡の神社の一つです。",
