        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29386:wikipedia:5b4bfb042bdb",
    "cityId": "29386",
    "category": "歴史",
    "text": "御杖神社は1546年の争乱で荒廃し、1554年に再建されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29386:wikipedia:27452060d898",
    "cityId": "29386",
    "category": "歴史",
    "text": "御杖神社は、1873年に郷社と定められました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BE%A1%E6%9D%96%E7%A5%9E%E7%A4%BE&oldid=106920097",
  },
  {
    "id": "29401:wikipedia:5f5f4f3c6d92",
    "cityId": "29401",
    "category": "自然",
    "text": "高取町の町の木はカエデ、町の花はツツジです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:d05df6ddd4c4",
    "cityId": "29401",
    "category": "地理",
    "text": "高取町は、古代の都があった飛鳥の南に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:32eab9b8b750",
    "cityId": "29401",
    "category": "自然",
    "text": "高取町を流れる高取川や曽我川は、大和川の水系に属しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:ce46d8caf5c6",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取町周辺は、飛鳥から吉野や紀伊へ向かう道の途中にあたります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:f0356e020e44",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取町周辺には、渡来系の氏族である東漢氏が定着しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:ea0bc4e1ff14",
    "cityId": "29401",
    "category": "歴史",
    "text": "日本書紀には、676年に高取山周辺の森林伐採を禁じた記述があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:e1efce6c2448",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取町周辺には、古代の波多郷に関係する地名が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:77273ef322ef",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取城は、越智氏の貝吹山城を支える支城として始まったとされています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:09fbd00df483",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取は、豊臣秀長が大和の国主となった時期にその領地となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:a0e0acab0a99",
    "cityId": "29401",
    "category": "歴史",
    "text": "江戸時代の高取藩は、本多氏の後に植村氏が治めました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:9f8b6825f807",
    "cityId": "29401",
    "category": "歴史",
    "text": "幕末の天誅組は高取城を攻めましたが、高取藩に退けられました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:3e39d8f63afc",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取村が初めて町になったのは1891年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:eb577938bea6",
    "cityId": "29401",
    "category": "歴史",
    "text": "現在の高取町は1954年、高取町・船倉村・越智岡村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:7ba54439bfc9",
    "cityId": "29401",
    "category": "産業",
    "text": "高取町は、薬づくりにゆかりの深い町です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:e10b97cc85e5",
    "cityId": "29401",
    "category": "古墳",
    "text": "高取町の市尾墓山古墳と市尾宮塚古墳は、古墳時代後期初頭の前方後円墳です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:2b7d1d80ea15",
    "cityId": "29401",
    "category": "古墳",
    "text": "高取町の市尾墓山古墳は、全長約66mあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:df8b2979ae20",
    "cityId": "29401",
    "category": "古墳",
    "text": "高取町の市尾宮塚古墳は、全長約44mあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:d29d2e510dab",
    "cityId": "29401",
    "category": "文化財",
    "text": "市尾墓山古墳と市尾宮塚古墳は、1981年に国の史跡となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:d62b27b32a88",
    "cityId": "29401",
    "category": "寺院",
    "text": "高取町の壷阪寺は、正式には南法華寺といいます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:86696ee4adf4",
    "cityId": "29401",
    "category": "寺院",
    "text": "高取町には、子嶋寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:40d45d4810e8",
    "cityId": "29401",
    "category": "古墳",
    "text": "高取町には、束明神古墳や与楽古墳群があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:dfcb64c60705",
    "cityId": "29401",
    "category": "町並み",
    "text": "高取町の土佐街道には、城下町の面影が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:90dc9a412319",
    "cityId": "29401",
    "category": "祭り",
    "text": "高取町の土佐街道一帯では、町家の雛まつりが行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:37fad334026a",
    "cityId": "29401",
    "category": "祭り",
    "text": "高取町では、高取城まつりが行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E7%94%BA&oldid=110617286",
  },
  {
    "id": "29401:wikipedia:adce343c52e1",
    "cityId": "29401",
    "category": "城",
    "text": "高取城は、備中松山城・岩村城と並ぶ日本三大山城の一つです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29401:wikipedia:df894becf581",
    "cityId": "29401",
    "category": "地理",
    "text": "高取城は、標高583mの高取山に築かれた山城です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29401:wikipedia:3327df15f89e",
    "cityId": "29401",
    "category": "建築",
    "text": "高取城には、白漆喰の天守や櫓が建ち並んでいました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29401:wikipedia:ddff56d61efc",
    "cityId": "29401",
    "category": "歴史",
    "text": "高取城は、1615年の一国一城令の際にも存続しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29401:wikipedia:e19a0aa2465f",
    "cityId": "29401",
    "category": "文化財",
    "text": "高取城跡には、石垣や堀、井戸などの遺構が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29401:wikipedia:58eb4040392a",
    "cityId": "29401",
    "category": "建築",
    "text": "高取城の二の門は、高取町の子嶋寺へ移されて山門となりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%AB%98%E5%8F%96%E5%9F%8E&oldid=111120707",
  },
  {
    "id": "29402:wikipedia:1cb974377d68",
    "cityId": "29402",
    "category": "自然",
    "text": "明日香村の村の木はツキ、村の花はタチバナです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:de2b25b2a382",
    "cityId": "29402",
    "category": "地理",
    "text": "明日香村は、奈良盆地の南端近くに位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:fb07ed7fa00f",
    "cityId": "29402",
    "category": "自然",
    "text": "明日香村には、飛鳥川や檜隈川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:0fa90d5ef0c2",
    "cityId": "29402",
    "category": "景観保全",
    "text": "明日香村は、村全域が古都保存法の対象となっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:3a7236a941c5",
    "cityId": "29402",
    "category": "景観保全",
    "text": "明日香村では、明日香村特別措置法によって歴史的な風土が守られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:8762bb36d1c5",
    "cityId": "29402",
    "category": "歴史",
    "text": "明日香村は1956年、阪合村・高市村・飛鳥村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:0ea2bbc0f6d1",
    "cityId": "29402",
    "category": "歴史",
    "text": "時代区分の「飛鳥時代」は、この地域の名に由来します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:672d37f0b0cc",
    "cityId": "29402",
    "category": "考古学",
    "text": "1972年、明日香村の高松塚古墳から彩色壁画が発見されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:b916625fb878",
    "cityId": "29402",
    "category": "交流",
    "text": "明日香村は1972年、韓国の扶余郡と姉妹都市提携を結びました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:f3b6b06bca71",
    "cityId": "29402",
    "category": "交通",
    "text": "明日香村の飛鳥駅は、近鉄吉野線の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:930d241379d4",
    "cityId": "29402",
    "category": "古墳",
    "text": "明日香村の石舞台古墳は、国の特別史跡です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:dbce5e8e3986",
    "cityId": "29402",
    "category": "古墳",
    "text": "明日香村のキトラ古墳も、国の特別史跡に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:f21e8445b29f",
    "cityId": "29402",
    "category": "古墳",
    "text": "明日香村には、牽牛子塚古墳や中尾山古墳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:ae0384631079",
    "cityId": "29402",
    "category": "古墳",
    "text": "明日香村には、岩屋山古墳やマルコ山古墳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29402:wikipedia:b22ba2986a72",
    "cityId": "29402",
    "category": "史跡",
    "text": "明日香村の野口王墓は、天武天皇と持統天皇の陵とされています。",
