        "https://ja.wikipedia.org/w/index.php?title=%E6%98%8E%E6%97%A5%E9%A6%99%E6%9D%91&oldid=110821649",
  },
  {
    "id": "29424:wikipedia:de6f8c72f0fa",
    "cityId": "29424",
    "category": "自然",
    "text": "上牧町の町の木はマキ、町の花はササユリです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:172993968715",
    "cityId": "29424",
    "category": "地理",
    "text": "上牧町は、馬見丘陵のほぼ中央に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:efc255d08555",
    "cityId": "29424",
    "category": "地名",
    "text": "上牧の名は、緩やかな丘陵が放牧に向いていたことに由来するとされています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:4da012329905",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧町一帯は、古代の大和国葛下郡に属していました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:7feff4cfe665",
    "cityId": "29424",
    "category": "歴史",
    "text": "江戸時代の上牧村は、郡山藩の領地でした。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:8758dca7f65f",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧村は1889年、上牧・下牧・中筋出作の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:d80e2a1354aa",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧村が上牧町になったのは1972年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:fabd124ef891",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧村は1897年、葛下郡から北葛城郡に所属が変わりました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:0b856cf5e98c",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧町では、1960年代から西大和ニュータウンの開発が進みました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:33c2d690df3e",
    "cityId": "29424",
    "category": "産業",
    "text": "上牧町では、草履や鼻緒の製造が行われてきました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:f2904e8946bc",
    "cityId": "29424",
    "category": "交通",
    "text": "上牧町内には、鉄道路線も駅もありません。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:b61dc8b77fee",
    "cityId": "29424",
    "category": "交通",
    "text": "上牧町の最寄り駅の一つは、町外にあるJR和歌山線の志都美駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:392aea1a16d1",
    "cityId": "29424",
    "category": "地名",
    "text": "上牧町の「松里園」は「しょうりえん」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:3a0b34f20fea",
    "cityId": "29424",
    "category": "地名",
    "text": "上牧町の「中筋出作」は「なかすじしゅつさく」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:0b517a277fa5",
    "cityId": "29424",
    "category": "地域",
    "text": "上牧町には、町の花にちなむ「ささゆり台」という地区があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:935cddc13b26",
    "cityId": "29424",
    "category": "神社",
    "text": "上牧町には、智照神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:8b4ca5319be1",
    "cityId": "29424",
    "category": "神社",
    "text": "上牧町の神社には、貴船神社や春日神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:89d225ae997c",
    "cityId": "29424",
    "category": "神社",
    "text": "上牧町には、伊邪那岐神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:07efc0a0b21d",
    "cityId": "29424",
    "category": "神社",
    "text": "上牧町には、二郡大神や穴大神があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:b371029402d5",
    "cityId": "29424",
    "category": "寺院",
    "text": "上牧町の寺院には、光専寺や浄安寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:200fe5d84dc3",
    "cityId": "29424",
    "category": "寺院",
    "text": "上牧町には、明善寺や教証寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:181156319d19",
    "cityId": "29424",
    "category": "寺院",
    "text": "上牧町には、念願寺や光隆寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:301aba17d3c8",
    "cityId": "29424",
    "category": "寺院",
    "text": "上牧町には、西念寺や即得寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:3ddffa408672",
    "cityId": "29424",
    "category": "寺院",
    "text": "上牧町には、教円寺や宗念寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:38062cf23c23",
    "cityId": "29424",
    "category": "温泉",
    "text": "上牧町には、大和神の牧温泉「虹の湯」があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:8169de5866fb",
    "cityId": "29424",
    "category": "歴史",
    "text": "1888年、別々の村になる合併案に対し、上牧村と下牧村は合同を申し出ました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29424:wikipedia:c318c0c5e039",
    "cityId": "29424",
    "category": "歴史",
    "text": "上牧村の役場は、1919年に南上牧から三軒屋へ移りました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8A%E7%89%A7%E7%94%BA&oldid=111267561",
  },
  {
    "id": "29425:wikipedia:3b1dffeaadfa",
    "cityId": "29425",
    "category": "自然",
    "text": "王寺町の町の木はウメ、町の花はサツキです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:655e31dfc658",
    "cityId": "29425",
    "category": "地理",
    "text": "王寺町は奈良県の北西部にあり、大阪府柏原市と接しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:c79142f80b09",
    "cityId": "29425",
    "category": "自然",
    "text": "王寺町の北側には、大和川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:f79a3644fee0",
    "cityId": "29425",
    "category": "地理",
    "text": "王寺町は、大和川が奈良県から大阪府へ流れ出る付近にあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:d158b1ddee44",
    "cityId": "29425",
    "category": "自然",
    "text": "王寺町内には、葛下川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:c38a67edc6b9",
    "cityId": "29425",
    "category": "交通",
    "text": "王寺駅には、JR大和路線・和歌山線と近鉄生駒線が乗り入れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:f71f255aa9df",
    "cityId": "29425",
    "category": "交通",
    "text": "王寺町の新王寺駅は、近鉄田原本線の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:09cc79b559e6",
    "cityId": "29425",
    "category": "交通",
    "text": "王寺町の畠田駅は、JR和歌山線の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:8d5824d9898c",
    "cityId": "29425",
    "category": "交通",
    "text": "王寺町は、国道25号と国道168号が交わる交通の要所です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:85ac4d8e5b9a",
    "cityId": "29425",
    "category": "地名",
    "text": "王寺という名は、聖徳太子建立と伝わる片岡王寺に由来するという説があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:0186485317c9",
    "cityId": "29425",
    "category": "寺院",
    "text": "片岡王寺は、放光寺とも呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:d73549715ca5",
    "cityId": "29425",
    "category": "地名",
    "text": "王寺の地名には、古代の「品治」が変化したという説もあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:8b717ffaffca",
    "cityId": "29425",
    "category": "歴史",
    "text": "王寺町一帯は、古代の品治郷にあたる地域です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:df3660c08827",
    "cityId": "29425",
    "category": "神社",
    "text": "王寺町には、延喜式に記された片岡神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:01b4768f94f1",
    "cityId": "29425",
    "category": "寺院",
    "text": "王寺町本町には、聖徳太子にゆかりのある達磨寺があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:3123e8346f76",
    "cityId": "29425",
    "category": "歴史",
    "text": "王寺町は、鉄道の開通とともに発展してきた「鉄道の町」です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:82e849c7fd3e",
    "cityId": "29425",
    "category": "歴史",
    "text": "王寺村は1889年、藤井村と王寺村が合併して誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:148051e2b297",
    "cityId": "29425",
    "category": "歴史",
    "text": "王寺村が王寺町になったのは1926年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:3c1f513f9c84",
    "cityId": "29425",
    "category": "歴史",
    "text": "1957年、香芝町の畠田の大部分が王寺町へ編入されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:30757b512083",
    "cityId": "29425",
    "category": "歴史",
    "text": "奈良駅と王寺駅を結ぶ鉄道は、1890年に開通しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:f2f0967ea514",
    "cityId": "29425",
    "category": "歴史",
    "text": "1892年、王寺から大阪の湊町駅へつながる鉄道路線が全通しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:1897ec0a6213",
    "cityId": "29425",
    "category": "橋",
    "text": "王寺駅南口と国道25号を結ぶ王寺大橋は、2008年に開通しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:7dbbe2a0946c",
    "cityId": "29425",
    "category": "自然",
    "text": "王寺町の明神山は、町の西側にある山です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:b9800d87e734",
    "cityId": "29425",
    "category": "史跡",
    "text": "王寺町には、孝霊天皇の片岡馬坂陵があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:d810e9ba1bd8",
    "cityId": "29425",
    "category": "地名",
    "text": "王寺町の「久度」は「くど」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:31a65a877bda",
    "cityId": "29425",
    "category": "地名",
    "text": "王寺町の「葛下」は「かつしも」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:0d6b46b1a80f",
    "cityId": "29425",
    "category": "地域文化",
    "text": "王寺町のキャッチフレーズは「和の鐘が鳴るまち王寺」です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:9dd2c0dbef0c",
    "cityId": "29425",
    "category": "文化",
    "text": "王寺町の「やわらぎ」は、十七条憲法の「和を以て貴しと為す」の精神を表しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:bd1c6b8ba540",
    "cityId": "29425",
    "category": "地域文化",
    "text": "王寺町の公式マスコットは「雪丸」です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29425:wikipedia:39af3c98f557",
    "cityId": "29425",
    "category": "伝承",
    "text": "王寺町の雪丸は、聖徳太子の愛犬とされる犬をモチーフにしています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E7%8E%8B%E5%AF%BA%E7%94%BA&oldid=109784856",
  },
  {
    "id": "29426:wikipedia:f60e1e5783e5",
    "cityId": "29426",
    "category": "自然",
    "text": "広陵町の町の木はモクセイ、町の花はヒマワリです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:62c3df79212c",
    "cityId": "29426",
    "category": "地理",
    "text": "広陵町の東部は平坦で、西部には丘陵地が広がっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:27b539d52667",
    "cityId": "29426",
    "category": "自然",
    "text": "広陵町では、高田川と葛城川が北へ流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:66e4da33a902",
    "cityId": "29426",
    "category": "自然",
    "text": "広陵町の東側には、曽我川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:a0d9a7cef9a5",
    "cityId": "29426",
    "category": "地域",
    "text": "真美ヶ丘ニュータウンは、広陵町と香芝市にまたがっています。",
