        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:73ea20aa5b5d",
    "cityId": "29426",
    "category": "古墳",
    "text": "広陵町の西部には、馬見古墳群が広がっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:8f4e71d955f7",
    "cityId": "29426",
    "category": "文学",
    "text": "広陵町の讃岐神社には、竹取物語にまつわる伝承があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:814e89dc9f79",
    "cityId": "29426",
    "category": "寺院",
    "text": "広陵町の百済寺には、三重塔が残っています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:6f0c78ba0144",
    "cityId": "29426",
    "category": "町並み",
    "text": "広陵町の南郷地区には、環濠集落が見られます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:bd93ffabf004",
    "cityId": "29426",
    "category": "歴史",
    "text": "広陵町の箸尾地区は、教行寺を中心とする寺内町として発展しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:53945d92f1c5",
    "cityId": "29426",
    "category": "地名",
    "text": "広陵町の町名は、「広瀬」の広と「丘陵」の陵を用いた中学校名に由来します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:321eb5c5e35a",
    "cityId": "29426",
    "category": "歴史",
    "text": "広陵町は1955年、馬見町・瀬南村・百済村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:dd0be6701315",
    "cityId": "29426",
    "category": "歴史",
    "text": "1956年、箸尾町が広陵町へ編入されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:501543f1d25d",
    "cityId": "29426",
    "category": "産業",
    "text": "広陵町は、靴下の生産で知られる町です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:f22f9e3edf15",
    "cityId": "29426",
    "category": "地域文化",
    "text": "広陵町は「かぐや姫のまち」というキャッチフレーズを掲げています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:1ad966402a3d",
    "cityId": "29426",
    "category": "農業",
    "text": "広陵町の農産物には、イチゴやナスがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:6abb2b38b24c",
    "cityId": "29426",
    "category": "交通",
    "text": "広陵町の箸尾駅は、近鉄田原本線の駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:854a4bdc90d0",
    "cityId": "29426",
    "category": "公園",
    "text": "広陵町には、竹取公園があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%BA%83%E9%99%B5%E7%94%BA&oldid=108696598",
  },
  {
    "id": "29426:wikipedia:615c977b8c31",
    "cityId": "29426",
    "category": "文化",
    "text": "広陵町の竹取公園には、柔道の野村豊和・野村忠宏をたたえる金メダルの塔が。",
