  {
    "id": "29427:wikipedia:78e1eebf068d",
    "cityId": "29427",
    "category": "歴史",
    "text": "河合町の西大和ニュータウンは、1960年代から開発されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%B2%B3%E5%90%88%E7%94%BA&oldid=110499575",
  },
