        "https://ja.wikipedia.org/w/index.php?title=%E6%B2%B3%E5%90%88%E7%94%BA&oldid=110499575",
  },
  {
    "id": "29427:wikipedia:98407df7170c",
    "cityId": "29427",
    "category": "地名",
    "text": "河合町の「薬井」は「くすりい」と読みます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E6%B2%B3%E5%90%88%E7%94%BA&oldid=110499575",
  },
  {
    "id": "29427:wikipedia:6361c54090e9",
    "cityId": "29427",
    "category": "地名",
    "text": "河合町の「山坊」は「やまのぼう」と読みます。",
