        "https://ja.wikipedia.org/w/index.php?title=%E6%B2%B3%E5%90%88%E7%94%BA&oldid=110499575",
  },
  {
    "id": "29427:wikipedia:6354f0d69349",
    "cityId": "29427",
    "category": "歴史",
    "text": "河合町一帯は、古代の大和国広瀬郡に属していました。",
