        "https://ja.wikipedia.org/w/index.php?title=%E6%B2%B3%E5%90%88%E7%94%BA&oldid=110499575",
  },
  {
    "id": "29441:wikipedia:0d51bf650ce9",
    "cityId": "29441",
    "category": "地理",
    "text": "吉野町の中央部には、吉野川が流れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:3ed4fb6d83dc",
    "cityId": "29441",
    "category": "自然",
    "text": "吉野町の北には竜門山地、南には大峰山系の山々が連なっています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:a83c97ac6363",
    "cityId": "29441",
    "category": "自然",
    "text": "吉野町の竜門岳は、標高904mです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:7dcde7b92ae3",
    "cityId": "29441",
    "category": "自然",
    "text": "吉野町には、ダム湖の津風呂湖があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:04bdb29aedbb",
    "cityId": "29441",
    "category": "地理",
    "text": "吉野町では、高見川が吉野川に合流します。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:3942c1b83cfd",
    "cityId": "29441",
    "category": "歴史",
    "text": "吉野町の宮滝には、古代の離宮である吉野宮が置かれていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:e480130ae831",
    "cityId": "29441",
    "category": "歴史",
    "text": "持統天皇は、たびたび吉野へ行幸しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:0daaca5cf110",
    "cityId": "29441",
    "category": "歴史",
    "text": "天武天皇は、壬申の乱に先立って吉野に身を寄せていました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:07a942125561",
    "cityId": "29441",
    "category": "歴史",
    "text": "源義経は、兄・頼朝の追及を逃れる途中で吉野に立ち寄ったとされています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:4bbf462be720",
    "cityId": "29441",
    "category": "文学",
    "text": "歌人の西行は、吉野に隠居したことがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:95fcc87ba71a",
    "cityId": "29441",
    "category": "歴史",
    "text": "吉野は南朝の拠点となり、後醍醐天皇が朝廷を置きました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:d22d30ee8000",
    "cityId": "29441",
    "category": "歴史",
    "text": "豊臣秀吉は、吉野で大規模な花見を行いました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:29a972ec6df2",
    "cityId": "29441",
    "category": "歴史",
    "text": "吉野村が町になったのは1928年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:5a61233e2ae7",
    "cityId": "29441",
    "category": "歴史",
    "text": "現在の吉野町は1956年、吉野町・上市町と4村の合併で誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:3d22f9718acd",
    "cityId": "29441",
    "category": "世界遺産",
    "text": "吉野山は2004年、「紀伊山地の霊場と参詣道」の一部として世界遺産に登録。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:f40ece3aa880",
    "cityId": "29441",
    "category": "地域文化",
    "text": "吉野町は2012年、「日本で最も美しい村」連合に加盟しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:426c3f09c17a",
    "cityId": "29441",
    "category": "産業",
    "text": "吉野町では、貯木場を中心に木材の取引や製材業が発展しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:53ab0f1e6a67",
    "cityId": "29441",
    "category": "工芸",
    "text": "吉野町では、製材の端材を活用した割り箸も作られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:c69a6ae02de4",
    "cityId": "29441",
    "category": "食文化",
    "text": "吉野町では、古くから日本酒が造られてきました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:00ac17560d6e",
    "cityId": "29441",
    "category": "地名",
    "text": "吉野町の上市という地名には、吉野川沿いの市場町だった歴史が表れています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:250a8d1f928d",
    "cityId": "29441",
    "category": "交通",
    "text": "吉野町には、千本口と吉野山を結ぶ吉野ロープウェイがあります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:428995dedd3a",
    "cityId": "29441",
    "category": "文化財",
    "text": "吉野町の金峯山寺では、本堂と仁王門が国宝に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:ce5ddb7e1dce",
    "cityId": "29441",
    "category": "神社",
    "text": "吉野町の吉野水分神社は、世界遺産の構成資産です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:afc736be50fe",
    "cityId": "29441",
    "category": "神社",
    "text": "吉野町の吉水神社も、世界遺産の構成資産です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:5925e5b3e5b2",
    "cityId": "29441",
    "category": "寺院",
    "text": "吉野町の如意輪寺の境内には、後醍醐天皇の陵があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:01e2bf02fde8",
    "cityId": "29441",
    "category": "寺院",
    "text": "吉野町には、桜本坊・竹林院・東南院などの寺院があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:3de4c8fe62be",
    "cityId": "29441",
    "category": "伝統芸能",
    "text": "吉野町の浄見原神社には、国栖奏という古い芸能が伝えられています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:bb18d4cee0cf",
    "cityId": "29441",
    "category": "祭り",
    "text": "吉野町の金峯山寺では、鬼火の祭典が行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:e9c1fa568e51",
    "cityId": "29441",
    "category": "祭り",
    "text": "吉野町の金峯山寺では、7月に蛙飛び行事が行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29441:wikipedia:d8af627e0507",
    "cityId": "29441",
    "category": "祭り",
    "text": "吉野水分神社では、春にお田植祭が行われます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E5%90%89%E9%87%8E%E7%94%BA&oldid=108817628",
  },
  {
    "id": "29443:wikipedia:e4f97fd24fae",
    "cityId": "29443",
    "category": "自然",
    "text": "下市町の町の木はスギ、町の花はマツバボタンです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:9839a0c777a1",
    "cityId": "29443",
    "category": "地理",
    "text": "下市町は、吉野川の南側に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:d41fa80680ab",
    "cityId": "29443",
    "category": "自然",
    "text": "下市町には、櫃ヶ岳や栃原岳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:8c90b6d65da0",
    "cityId": "29443",
    "category": "町並み",
    "text": "下市町の中心部には、秋野川に沿って町並みが延びています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:353c8697dc34",
    "cityId": "29443",
    "category": "景観",
    "text": "「秋野川沿いの下市の町なみ」は、奈良県景観資産に登録されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:654b4c0a5dac",
    "cityId": "29443",
    "category": "歴史",
    "text": "下市村が町になったのは1890年です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:c4ca96f3be6c",
    "cityId": "29443",
    "category": "歴史",
    "text": "1956年、秋野村と丹生村が下市町へ編入されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:c1fa7b00579c",
    "cityId": "29443",
    "category": "交通",
    "text": "下市町に鉄道の駅はなく、吉野川の対岸にある下市口駅が最寄り駅です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:a5c39a2655a3",
    "cityId": "29443",
    "category": "寺院",
    "text": "下市町の願行寺は、「下市御坊」とも呼ばれます。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:36abb8e48932",
    "cityId": "29443",
    "category": "庭園",
    "text": "下市町の願行寺の庭園は、奈良県の名勝です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:5cfddfbf6336",
    "cityId": "29443",
    "category": "文化財",
    "text": "下市町の願行寺の本堂や鐘楼は、町の文化財に指定されています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:fe1315198958",
    "cityId": "29443",
    "category": "神社",
    "text": "下市町には、波比売神社があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:0b7bf1913dc4",
    "cityId": "29443",
    "category": "花",
    "text": "下市町の広橋梅林は、梅の名所です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:02b9f5f33034",
    "cityId": "29443",
    "category": "自然",
    "text": "下市町には、森林公園やすらぎ村があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:71a9a18c99f4",
    "cityId": "29443",
    "category": "温泉",
    "text": "下市町には、下市温泉があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29443:wikipedia:be6bd24197f8",
    "cityId": "29443",
    "category": "文化",
    "text": "下市町には、拓本の里「拓美の園」があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E4%B8%8B%E5%B8%82%E7%94%BA&oldid=110140126",
  },
  {
    "id": "29444:wikipedia:a1e0ebe49c9d",
    "cityId": "29444",
    "category": "地理",
    "text": "黒滝村は「奈良のへそ」をキャッチフレーズにしています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:8adbb78954a0",
    "cityId": "29444",
    "category": "自然",
    "text": "黒滝村では、村の面積の約97％を林野が占めています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:59699b686c41",
    "cityId": "29444",
    "category": "産業",
    "text": "黒滝村は、吉野杉の産地として知られています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:6b08d15e267a",
    "cityId": "29444",
    "category": "地理",
    "text": "黒滝村は、大峰山脈北部の山間に位置しています。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:60c38cfad2a3",
    "cityId": "29444",
    "category": "自然",
    "text": "黒滝村の山には、大天井ヶ岳や四寸岩山があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:61368ebf5552",
    "cityId": "29444",
    "category": "自然",
    "text": "黒滝村には、百貝岳があります。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:285162e0a013",
    "cityId": "29444",
    "category": "自然",
    "text": "黒滝村を流れる黒滝川は、紀の川水系の川です。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:ad9e869a0baf",
    "cityId": "29444",
    "category": "歴史",
    "text": "黒滝村は1912年、南芳野村が分かれて誕生しました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:7af0f9b9769d",
    "cityId": "29444",
    "category": "歴史",
    "text": "1949年、黒滝村の才谷地区は秋野村へ編入されました。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
    "id": "29444:wikipedia:745faa10deff",
    "cityId": "29444",
    "category": "食文化",
    "text": "黒滝村では、コンニャクづくりが盛んです。",
    "source":
        "https://ja.wikipedia.org/w/index.php?title=%E9%BB%92%E6%BB%9D%E6%9D%91&oldid=108928921",
  },
  {
